INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(250, 'alumni', '/əˈlʌmnaɪ/', 'noun', '{"zh-TW":["校友"],"en":["former students of a school or university"]}', NULL, 'alumni association / alumni network', '[{"en":"The alumni donated to the school.","zh-TW":"校友們捐款給學校。"},{"en":"She joined the alumni association.","zh-TW":"她加入了校友會。"}]', NULL, NULL, 2, 250, NULL),
(251, 'alumni network', '/''æˌlʌmnaɪ ˌnetwɜːrk/', 'noun', '{"zh-TW":["校友網絡；校友會"],"en":["a group of former students of a school or university who maintain connections and support each other professionally"]}', NULL, 'join the alumni network / leverage the alumni network / active alumni network', '[{"en":"She found her job through connections in her university''s alumni network.","zh-TW":"她通過大學校友網絡的人脈找到了工作。"},{"en":"A strong alumni network can provide mentorship, references, and job opportunities.","zh-TW":"強大的校友網絡可以提供指導、推薦信和就業機會。"}]', NULL, NULL, 5, 251, NULL),
(252, 'always', '/ˈɔːlweɪz/', 'adverb', '{"zh-TW":["總是；一直"],"en":["at all times"]}', NULL, 'always available / as always', '[{"en":"He is always punctual.","zh-TW":"他總是很準時。"},{"en":"Customers always come first.","zh-TW":"客戶永遠是第一位的。"}]', '{"adverb":"always"}', NULL, 2, 252, NULL),
(253, 'amalgamate', '/əˈmælɡəmeɪt/', 'verb', '{"zh-TW":["合併；融合"],"en":["to combine or unite to form one organization or structure"]}', NULL, 'amalgamate companies / amalgamate departments', '[{"en":"The two regional offices were amalgamated into one.","zh-TW":"兩個區域辦公室被合併為一個。"},{"en":"The union decided to amalgamate with a larger federation.","zh-TW":"工會決定與一個更大的聯合會合併。"}]', '{"noun":"amalgamation","adjective":"amalgamated"}', NULL, 4, 253, NULL),
(254, 'amalgamation', '/əˌmælɡəˈmeɪʃən/', 'noun', '{"zh-TW":["合並；融合"],"en":["the combination of several elements into a single more effective whole"]}', NULL, 'corporate amalgamation / amalgamation of departments / complete amalgamation', '[{"en":"The amalgamation of three departments reduced administrative overhead.","zh-TW":"三個部門的合並降低了行政費用。"},{"en":"The amalgamation of two rival unions created a more powerful bargaining group.","zh-TW":"兩個競爭工會的合並創建了一個更強大的談判群體。"}]', '{"verb":"amalgamate","adjective":"amalgamated"}', NULL, 4, 254, NULL),
(255, 'amazing', '/əˈmeɪzɪŋ/', 'adjective', '{"zh-TW":["令人驚嘆的；了不起的"],"en":["extremely surprising or impressive"]}', NULL, 'amazing + 名詞 / It''s amazing that...', '[{"en":"The view from the top was amazing.","zh-TW":"從頂端看下去的景色令人驚嘆。"},{"en":"She did an amazing job on the project.","zh-TW":"她在專案中表現出色。"}]', '{"verb":"amaze","noun":"amazement","adverb":"amazingly"}', NULL, 3, 255, NULL),
(256, 'ambitious', '/æmˈbɪʃəs/', 'adjective', '{"zh-TW":["有野心的；雄心勃勃的"],"en":["having a strong desire to succeed","requiring great effort"]}', '{"root":{"text":"ambi","meaning":"go around (四處走)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿四處尋求機會的特質，即「有野心的」。"}', 'ambitious plan/goal/target; ambitious goal / ambitious plan', '[{"en":"The company set ambitious growth targets for next year.","zh-TW":"公司為明年設定了雄心勃勃的成長目標。"},{"en":"She is an ambitious young professional.","zh-TW":"她是一位有抱負的年輕專業人士。"},{"en":"She is an ambitious young woman.","zh-TW":"她是個有抱負的年輕女性。"},{"en":"The project is ambitious but achievable.","zh-TW":"這個計畫雄心勃勃但可實現。"}]', '{"noun":"ambition","adverb":"ambitiously"}', NULL, 3, 256, 823),
(257, 'ambivalence', '/æmˈbɪvələns/', 'noun', '{"zh-TW":["矛盾情感；態度不明確"],"en":["the state of having mixed feelings about something"]}', NULL, 'feel ambivalence / express ambivalence / ambivalence toward', '[{"en":"Her ambivalence about the project delayed the decision.","zh-TW":"她對該項目的矛盾情感拖延了決策。"},{"en":"There is a general ambivalence toward automation in the workforce.","zh-TW":"工作人員對自動化普遍持矛盾態度。"}]', '{"adjective":"ambivalent","adverb":"ambivalently"}', NULL, 4, 257, NULL),
(258, 'ambivalent', '/''æmˈbɪvələnt/', 'adjective', '{"zh-TW":["矛盾的；態度不明確的"],"en":["having mixed feelings or contradictory ideas about something or someone"]}', NULL, 'ambivalent attitude / feel ambivalent / remain ambivalent', '[{"en":"She felt ambivalent about accepting the job offer because it required relocating.","zh-TW":"她對接受這份工作要約感到矛盾，因為它需要搬遷。"},{"en":"The board was ambivalent about the acquisition, seeing both opportunities and risks.","zh-TW":"董事會對收購態度矛盾，看到了機遇和風險。"}]', '{"adverb":"ambivalently","noun":"ambivalence"}', NULL, 4, 258, NULL),
(259, 'ambulance', '/ˈæmbjʊləns/', 'noun', '{"zh-TW":["救護車"],"en":["a vehicle for taking sick people to hospital"]}', NULL, 'call an ambulance / emergency ambulance', '[{"en":"Call an ambulance immediately if someone collapses.","zh-TW":"如果有人倒下，立即叫救護車。"},{"en":"The ambulance arrived within five minutes.","zh-TW":"救護車在五分鐘內到達。"}]', NULL, NULL, 3, 259, NULL),
(260, 'ameliorate', '/əˈmiːliəreɪt/', 'verb', '{"zh-TW":["改善；改良"],"en":["to make something bad or unsatisfactory better"]}', NULL, 'ameliorate conditions / ameliorate suffering / ameliorate the situation', '[{"en":"Policy interventions can ameliorate the effects of poverty on children.","zh-TW":"政策干預可以改善貧困對兒童的影響。"},{"en":"The new protocol was designed to ameliorate systemic risks.","zh-TW":"新協議旨在改善系統性風險。"}]', '{"noun":"amelioration","adjective":"ameliorative"}', NULL, 4, 260, NULL),
(261, 'amelioration', '/əˌmiːliəˈreɪʃən/', 'noun', '{"zh-TW":["改善；改進"],"en":["the act of making something better"]}', NULL, 'policy amelioration / condition amelioration / seek amelioration', '[{"en":"The international aid focused on amelioration of the refugee crisis.","zh-TW":"國際援助重點是對難民危機的改善。"},{"en":"Amelioration of working conditions improved staff morale significantly.","zh-TW":"工作條件的改善顯著提高了員工士氣。"}]', '{"verb":"ameliorate","adjective":"ameliorated"}', NULL, 4, 261, NULL),
(262, 'ameliorative', '/əˈmiːliərətɪv/', 'adjective', '{"zh-TW":["改善的；有助改進的"],"en":["tending to improve or alleviate a bad situation"]}', NULL, 'ameliorative policy / ameliorative measure / ameliorative action', '[{"en":"Ameliorative policies reduced poverty rates among the elderly.","zh-TW":"改善性政策降低了老年人的貧困率。"},{"en":"Ameliorative actions were taken to address the environmental damage.","zh-TW":"採取了改善性行動來處理環境損害。"}]', '{"verb":"ameliorate","noun":"amelioration"}', NULL, 4, 262, NULL),
(263, 'amend', '/əˈmend/', 'verb', '{"zh-TW":["修正；修訂"],"en":["to make changes to improve or correct","to make changes to a document or law"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mend","meaning":"fault (過錯)"},"logic":"朝向修正過錯，即「修訂」。"}', 'amend a contract/law/policy; amend a law / amend the constitution', '[{"en":"The contract was amended to include new terms.","zh-TW":"合約被修訂以納入新條款。"},{"en":"Congress voted to amend the legislation.","zh-TW":"國會投票修正了該立法。"},{"en":"The committee voted to amend the proposal.","zh-TW":"委員會投票修正了提案。"},{"en":"The law was amended to include new provisions.","zh-TW":"法律被修訂以納入新條款。"}]', '{"noun":"amendment"}', NULL, 2, 263, 643),
(264, 'amendment', '/əˈmɛndmənt/', 'noun', '{"zh-TW":["修正案"],"en":["a change made to a law or document"]}', NULL, 'constitutional amendment / first amendment', '[{"en":"The First Amendment protects free speech.","zh-TW":"第一修正案保護言論自由。"},{"en":"They proposed an amendment to the bill.","zh-TW":"他們提議修改法案。"}]', '{"verb":"amend"}', NULL, 3, 264, 261),
(265, 'amenities', '/əˈmiːnɪtiz/', 'noun', '{"zh-TW":["設施；便民設施"],"en":["useful features that make a place pleasant or convenient"]}', NULL, 'local amenities / property amenities', '[{"en":"The apartment is close to many local amenities.","zh-TW":"這棟公寓靠近許多當地便民設施。"},{"en":"The development includes amenities such as a gym and pool.","zh-TW":"該開發項目包括健身房和游泳池等設施。"}]', NULL, NULL, 3, 265, NULL),
(266, 'amenity', '/əˈmiːnɪti/', 'noun', '{"zh-TW":["設施；便利設備"],"en":["a useful or desirable feature of a place"]}', NULL, 'hotel amenity / modern amenity', '[{"en":"The resort offers excellent amenities including a spa.","zh-TW":"度假村提供包括水療在內的優質設施。"},{"en":"Please check the list of in-room amenities.","zh-TW":"請查看客房設施清單。"}]', NULL, NULL, 3, 266, NULL),
(267, 'amenity kit', '/əˈmenɪti kɪt/', 'noun', '{"zh-TW":["旅行盥洗包"],"en":["a bag of toiletries and essentials provided to passengers"]}', NULL, 'business class amenity kit / complimentary amenity kit', '[{"en":"Passengers in business class received an amenity kit.","zh-TW":"商務艙乘客收到了旅行盥洗包。"},{"en":"The amenity kit included a sleep mask, toothbrush, and earplugs.","zh-TW":"盥洗包內含睡眠眼罩、牙刷和耳塞。"}]', NULL, NULL, 4, 267, NULL),
(268, 'among', '/əˈmʌŋ/', 'preposition', '{"zh-TW":["在…之中","在...之中；之間"],"en":["in the middle of; surrounded by","in the middle of; between more than two"]}', NULL, 'among others / among the best; among others (其中)', '[{"en":"She is among the top candidates.","zh-TW":"她是頂尖的候選人之一。"},{"en":"Divide the tasks among the team.","zh-TW":"把任務分配給團隊成員。"},{"en":"She sat among her friends.","zh-TW":"她坐在朋友們中間。"},{"en":"He is among the best students.","zh-TW":"他是最好的學生之一。"},{"en":"She is popular among her colleagues.","zh-TW":"她在同事之間很受歡迎。"},{"en":"The cost was divided among the team members.","zh-TW":"費用在團隊成員之間分攤。"}]', '{"preposition":"among"}', NULL, 2, 268, NULL),
(269, 'amortization', '/əˌmɔːrtɪˈzeɪʃən/', 'noun', '{"zh-TW":["攤銷"],"en":["the gradual write-off of an intangible asset over time"]}', NULL, 'loan amortization / amortization schedule / amortization of goodwill', '[{"en":"The amortization of goodwill impacts reported earnings.","zh-TW":"商譽攤銷影響報告的盈利。"},{"en":"He prepared an amortization schedule for the loan.","zh-TW":"他為貸款準備了攤銷時間表。"}]', '{"verb":"amortize","adjective":"amortized"}', NULL, 4, 269, NULL),
(270, 'amortization schedule', '/əˌmɔːrtɪˈzeɪʃən ˈʃedjuːl/', 'noun', '{"zh-TW":["分期攤還計劃"],"en":["a table showing each loan payment broken down into principal and interest"]}', NULL, 'follow the amortization schedule / amortization schedule calculation', '[{"en":"The amortization schedule shows the loan is paid off in 10 years.","zh-TW":"分期攤還計劃顯示貸款將在10年內還清。"},{"en":"Each payment in the amortization schedule reduces the outstanding principal.","zh-TW":"分期攤還計劃中的每次付款都減少了未償還本金。"}]', NULL, NULL, 5, 270, NULL),
(271, 'amortize', '/ˈæmɔːrtaɪz/', 'verb', '{"zh-TW":["攤銷；分期償還"],"en":["to spread the cost of an asset over its useful life"]}', NULL, 'amortize a loan / amortize intangible assets', '[{"en":"The loan was amortized over 10 years with equal monthly payments.","zh-TW":"貸款以等額月付方式在10年內攤銷。"},{"en":"Software development costs were amortized over five years.","zh-TW":"軟體開發成本在五年內攤銷。"}]', '{"noun":"amortization","adjective":"amortized"}', NULL, 3, 271, NULL),
(272, 'amount', '/əˈmaʊnt/', 'noun', '{"zh-TW":["金額；數量"],"en":["a quantity of something","the total of two or more quantities"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mount","meaning":"mountain (山)"},"logic":"朝向堆積如山，即「數量」。"}', 'a large/small amount of / total amount', '[{"en":"The total amount due is $5,000.","zh-TW":"應付總金額為5,000美元。"},{"en":"A significant amount of time was spent on research.","zh-TW":"大量時間被用於研究。"}]', NULL, NULL, 2, 272, NULL),
(273, 'anachronism', '/əˈnækrənɪzəm/', 'noun', '{"zh-TW":["時代錯誤；不合時宜的事物"],"en":["something that belongs to a different period of time and seems outdated"]}', NULL, 'an anachronism / political anachronism / cultural anachronism', '[{"en":"The use of fax machines in modern offices is an anachronism.","zh-TW":"在現代辦公室使用傳真機是一種時代錯誤。"},{"en":"The ancient ritual is viewed as an anachronism in contemporary society.","zh-TW":"這個古老的儀式在當代社會被視為不合時宜的事物。"}]', '{"adjective":"anachronistic","adverb":"anachronistically"}', NULL, 4, 273, NULL),
(274, 'anaerobic', '/''ænəˈrəʊbɪk/', 'adjective', '{"zh-TW":["無氧的；厭氧的"],"en":["relating to physical exercise that is intense but of short duration, not requiring oxygen as fuel"]}', NULL, 'anaerobic exercise / anaerobic training / anaerobic capacity', '[{"en":"Sprinting and weightlifting are examples of anaerobic exercise.","zh-TW":"短跑和舉重是無氧運動的例子。"},{"en":"Anaerobic training builds muscle strength and power more effectively than aerobic exercise.","zh-TW":"無氧訓練比有氧運動更有效地建立肌肉力量和爆發力。"}]', NULL, NULL, 3, 274, NULL),
(275, 'anaerobic training', '/''ænˌeəˌrəʊbɪk ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["無氧訓練"],"en":["high-intensity physical activity performed without oxygen, used to build strength and speed"]}', NULL, 'benefit of anaerobic training / incorporate anaerobic training / anaerobic training session', '[{"en":"Anaerobic training like sprinting and weight lifting builds explosive muscle power.","zh-TW":"無氧訓練如短跑和舉重可以建立爆發性的肌肉力量。"},{"en":"Athletes combine aerobic and anaerobic training to maximize overall fitness.","zh-TW":"運動員結合有氧和無氧訓練以最大化整體健康。"}]', '{"adjective":"anaerobic"}', NULL, 5, 275, NULL),
(276, 'analgesia', '/ˌænəlˈdʒiːziə/', 'noun', '{"zh-TW":["止痛；鎮痛"],"en":["the inability to feel pain; or the condition produced by analgesic drugs"]}', NULL, 'provide analgesia / epidural analgesia / adequate analgesia', '[{"en":"Epidural analgesia is commonly used during labor for pain relief.","zh-TW":"硬膜外鎮痛常用於分娩期間的止痛。"},{"en":"Patient-controlled analgesia gives patients autonomy over their pain relief.","zh-TW":"患者自控鎮痛讓患者自主控制止痛。"}]', '{"adjective":"analgesic","noun":"analgesic"}', NULL, 3, 276, NULL),
(277, 'analogy', '/əˈnælədʒi/', 'noun', '{"zh-TW":["類比；比喻"],"en":["a comparison between two things for the purpose of explanation"]}', NULL, 'draw an analogy / apt analogy / analogy between', '[{"en":"The teacher drew an analogy between electricity and water flow.","zh-TW":"老師以電流和水流之間的類比作說明。"},{"en":"An analogy can make complex ideas easier to understand.","zh-TW":"類比可以使複雜的概念更易於理解。"}]', '{"adjective":"analogous","adverb":"analogously"}', NULL, 3, 277, NULL),
(278, 'analysis', 'əˈnæləsɪs', 'noun', '{"zh-TW":["分析；研究","分解"],"en":["a detailed examination","a study of data"]}', NULL, 'cost analysis/market analysis', '[{"en":"Please present a market analysis.","zh-TW":"請提交市場分析。"}]', '{"verb":"analyze","adjective":"analytical","adverb":"analytically"}', NULL, 3, 278, NULL),
(279, 'analyst', '/ˈænəlɪst/', 'noun', '{"zh-TW":["分析師；分析人員"],"en":["a professional who examines data or situations to draw conclusions"]}', NULL, 'financial analyst / business analyst / data analyst / market analyst', '[{"en":"The financial analyst issued a buy recommendation on the stock.","zh-TW":"財務分析師對該股票發出了買入建議。"},{"en":"She works as a business analyst in the strategy department.","zh-TW":"她在策略部門擔任業務分析師。"}]', '{"plural":"analysts","verb":"analyze"}', NULL, 3, 279, NULL),
(280, 'analytical thinking', '/ˌænəˈlɪtɪkəl ˈθɪŋkɪŋ/', 'noun', '{"zh-TW":["分析性思維；分析思維"],"en":["the ability to systematically break down complex problems and evaluate information to reach conclusions"]}', NULL, 'develop analytical thinking / strong analytical thinking / apply analytical thinking', '[{"en":"Analytical thinking helps professionals identify patterns and solve complex problems.","zh-TW":"分析性思維幫助專業人士識別規律並解決複雜問題。"},{"en":"Employers value candidates who demonstrate strong analytical thinking in interviews.","zh-TW":"雇主重視在面試中展示強大分析性思維的候選人。"}]', NULL, NULL, 5, 280, NULL),
(281, 'analytics', '/ˌænəˈlɪtɪks/', 'noun', '{"zh-TW":["分析；數據分析"],"en":["systematic computational analysis of data"]}', NULL, 'marketing analytics / data analytics', '[{"en":"Analytics revealed that most customers visit the site on mobile.","zh-TW":"分析顯示大多數顧客使用手機訪問網站。"},{"en":"The analytics team provided insights to improve the campaign.","zh-TW":"分析團隊提供了改進活動的見解。"}]', '{"verb":"analyze","adjective":"analytical"}', NULL, 3, 281, NULL),
(282, 'analyze', '/ˈænəlaɪz/', 'verb', '{"zh-TW":["分析；解析","分析"],"en":["to examine something in detail to understand it","to examine in detail"]}', '{"root":{"text":"ana","meaning":"up/throughout (全面)"},"suffix":{"text":"-lyze","meaning":"loosen/break down (分解)"},"logic":"全面分解，即「分析」。"}', 'analyze data/results/trends; analyze data / analyze results', '[{"en":"The team will analyze the survey results next week.","zh-TW":"團隊將在下週分析調查結果。"},{"en":"We need to analyze market trends before launching.","zh-TW":"推出前我們需要分析市場趨勢。"},{"en":"Scientists analyzed the data carefully.","zh-TW":"科學家仔細分析了數據。"},{"en":"We need to analyze the market trends.","zh-TW":"我們需要分析市場趨勢。"}]', '{"noun":"analysis","adjective":"analytical","noun2":"analyst"}', NULL, 3, 282, 262),
(283, 'anchor investor', '/ˈæŋkər ɪnˈvestər/', 'noun', '{"zh-TW":["錨定投資者"],"en":["a cornerstone investor who commits to a significant portion of an IPO or placement"]}', NULL, 'secure an anchor investor / role of anchor investor / anchor investor commitment', '[{"en":"The fund secured an anchor investor to give confidence to other buyers.","zh-TW":"基金獲得了錨定投資者以給予其他買家信心。"},{"en":"Anchor investors stabilize IPO pricing and signal confidence in the offering.","zh-TW":"錨定投資者穩定IPO定價並向發行傳遞信心訊號。"}]', NULL, NULL, 5, 283, NULL),
(284, 'anchoring effect', '/''æŋkərɪŋ ɪˌfekt/', 'noun', '{"zh-TW":["定錨效應；錨點偏誤"],"en":["the tendency to rely too heavily on the first piece of information offered when making decisions"]}', NULL, 'use the anchoring effect / beware of the anchoring effect / anchoring effect in negotiation', '[{"en":"Negotiators often use the anchoring effect by making the first offer to set the reference point.","zh-TW":"談判者通常通過先報價來設定參考點，利用定錨效應。"},{"en":"The anchoring effect explains why initial prices greatly influence what consumers consider reasonable.","zh-TW":"定錨效應解釋了為什麼初始價格對消費者認為合理的價格有很大影響。"}]', '{"noun":"anchor","verb":"anchor"}', NULL, 5, 284, NULL),
(285, 'ancillary', '/ˈænsɪləri/', 'adjective', '{"zh-TW":["輔助的；附屬的"],"en":["providing support to a primary activity; additional"]}', NULL, 'ancillary services / ancillary costs / ancillary staff', '[{"en":"Ancillary services such as catering and cleaning support the core business.","zh-TW":"餐飲和清潔等輔助服務支持核心業務。"},{"en":"Ancillary costs can add twenty percent to the total project budget.","zh-TW":"輔助成本可能使項目總預算增加百分之二十。"}]', NULL, NULL, 3, 285, NULL),
(286, 'ancillary cost', '/ænˈsɪləri kɒst/', 'noun', '{"zh-TW":["附帶費用；輔助成本"],"en":["a secondary cost incurred in support of a primary activity or function"]}', NULL, 'include ancillary costs / ancillary cost budget', '[{"en":"Freight, customs, and insurance are ancillary costs of importing.","zh-TW":"貨運、海關和保險費是進口的附帶費用。"},{"en":"Ancillary costs can significantly increase the total project expenditure.","zh-TW":"附帶費用可能會顯著增加項目的總支出。"}]', NULL, NULL, 5, 286, NULL),
(287, 'ancillary service', '/ænˈsɪləri ˈsɜːrvɪs/', 'noun', '{"zh-TW":["輔助服務；附加服務"],"en":["a supplementary service that supports or complements the main service"]}', NULL, 'offer ancillary services / ancillary service charge', '[{"en":"The hotel generates revenue through ancillary services like parking.","zh-TW":"飯店通過停車等輔助服務產生收入。"},{"en":"Ancillary services are often bundled with the primary offering.","zh-TW":"輔助服務通常與主要產品捆綁在一起。"}]', NULL, NULL, 5, 287, NULL),
(288, 'anesthesia', '/ˌænɪsˈθiːziə/', 'noun', '{"zh-TW":["麻醉"],"en":["a state of induced insensitivity to pain for surgery"]}', NULL, 'general anesthesia / local anesthesia', '[{"en":"The patient was placed under general anesthesia for the operation.","zh-TW":"患者在手術中被施以全身麻醉。"},{"en":"Local anesthesia numbs only the specific area being treated.","zh-TW":"局部麻醉只會使正在治療的特定區域失去知覺。"}]', '{"noun":"anesthesiologist","adjective":"anesthetic"}', NULL, 4, 288, NULL),
(289, 'anesthesiologist', '/ˌænɪsˌθiːziˈɒlədʒɪst/', 'noun', '{"zh-TW":["麻醉科醫師"],"en":["a physician specializing in the administration of anesthesia"]}', NULL, 'consult an anesthesiologist / qualified anesthesiologist / experienced anesthesiologist', '[{"en":"The anesthesiologist monitored the patient throughout the surgery.","zh-TW":"麻醉科醫師在整個手術過程中監測患者。"},{"en":"An anesthesiologist assesses risks before administering general anesthesia.","zh-TW":"麻醉科醫師在施用全身麻醉前評估風險。"}]', NULL, NULL, 5, 289, NULL),
(290, 'angel investor', '/ˈeɪndʒəl ɪnˈvestər/', 'noun', '{"zh-TW":["天使投資人"],"en":["an individual who invests personal money in early-stage startups"]}', NULL, 'angel investor network / find an angel investor / pitch to angel investors', '[{"en":"An angel investor provided the initial capital to launch the company.","zh-TW":"天使投資人提供了啟動公司的初始資本。"},{"en":"Angel investors often provide mentorship in addition to funding.","zh-TW":"天使投資人除了資金外，通常還提供指導。"}]', '{"plural":"angel investors"}', NULL, 5, 290, NULL),
(291, 'angry', '/ˈæŋɡri/', 'adjective', '{"zh-TW":["生氣的","生氣的；憤怒的"],"en":["feeling strong displeasure","feeling or showing strong displeasure"]}', NULL, 'get angry / angry about; angry at / angry about; angry with/at sb / angry about sth', '[{"en":"The customer was angry about the delay.","zh-TW":"顧客對延誤感到生氣。"},{"en":"Don''t make hasty decisions when angry.","zh-TW":"生氣時不要做倉促的決定。"},{"en":"She was angry about the delay.","zh-TW":"她對延誤感到生氣。"},{"en":"Don''t be angry with me.","zh-TW":"別對我生氣。"},{"en":"He was angry about the delay.","zh-TW":"他對延誤感到憤怒。"}]', '{"adjective":"angry","noun":"anger","adverb":"angrily","verb":"anger"}', NULL, 2, 291, NULL),
(292, 'animal', '/ˈænɪməl/', 'noun', '{"zh-TW":["動物"],"en":["a living creature that is not a plant or human","a living creature that can move and feel"]}', NULL, 'wild animal / animal rights; domestic/wild animal', '[{"en":"Dogs are loyal animals.","zh-TW":"狗是忠誠的動物。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨滅絕。"},{"en":"Dogs are popular domestic animals.","zh-TW":"狗是受歡迎的家畜。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨絕種。"}]', NULL, NULL, 2, 292, NULL),
(293, 'annex', '/ˈæneks/', 'noun', '{"zh-TW":["附件；附屬建築"],"en":["an addition or supplement to a document; also an attached building"]}', NULL, 'attach an annex / annex to the report / building annex', '[{"en":"The technical specifications are detailed in the annex.","zh-TW":"技術規格在附件中有詳細說明。"},{"en":"A new annex was constructed to expand the office capacity.","zh-TW":"建造了新的附屬建築以擴大辦公室容量。"}]', '{"verb":"annex","adjective":"annexed"}', NULL, 2, 293, 983),
(294, 'anniversary', 'ˌænɪˈvɜːrsəri', 'noun', '{"zh-TW":["週年紀念；週年","週年慶"],"en":["the annual date of a past event","a celebration of longevity"]}', NULL, 'company anniversary/10th anniversary', '[{"en":"We are celebrating our 20th anniversary.","zh-TW":"我們正在慶祝20週年紀念日。"}]', '{"adjective":"annual","adverb":"annually"}', NULL, 4, 294, NULL),
(295, 'annotate', '/''ænəˌteɪt/', 'verb', '{"zh-TW":["注釋；加批注"],"en":["to add notes or comments to a text or diagram to explain or comment on it"]}', NULL, 'annotate a text / annotate a document / annotate with comments', '[{"en":"Students are encouraged to annotate their textbooks as they read.","zh-TW":"學生被鼓勵在閱讀時對教科書進行注釋。"},{"en":"The teacher asked students to annotate the poem with their interpretation of each stanza.","zh-TW":"老師要求學生對每節詩進行注釋，說明他們的理解。"}]', '{"noun":"annotation","adjective":"annotated"}', NULL, 3, 295, NULL),
(296, 'announce', '/əˈnaʊns/', 'verb', '{"zh-TW":["宣布；公告","宣布；宣告","宣布"],"en":["to make a public or official statement","to make something known publicly","to make a public statement about something"]}', '{"prefix":{"text":"an-","meaning":"toward (朝向)"},"root":{"text":"nounce","meaning":"report (報告)"},"logic":"朝向報告，即「宣布」。"}', 'announce a decision/plan/merger; announce a decision / announce that; announce the results / announce a decision / officially announce', '[{"en":"The CEO announced the merger at a press conference.","zh-TW":"執行長在記者會上宣布了合併消息。"},{"en":"The results will be announced next Monday.","zh-TW":"結果將於下週一公布。"},{"en":"They announced the winner.","zh-TW":"他們宣布了獲勝者。"},{"en":"The company announced a new product.","zh-TW":"公司宣布了一款新產品。"},{"en":"The company announced record profits.","zh-TW":"公司宣布了創紀錄的利潤。"},{"en":"They will announce the winner tomorrow.","zh-TW":"他們明天將宣布得獎者。"}]', '{"noun":"announcement","noun2":"announcer"}', NULL, 3, 296, 5),
(297, 'announcement', 'əˈnaʊnsmənt', 'noun', '{"zh-TW":["公告；通知","宣布"],"en":["an official public statement","a declaration"]}', NULL, 'make an announcement/company announcement', '[{"en":"The CEO made an important announcement.","zh-TW":"執行長發布了重要公告。"}]', '{"verb":"announce","adjective":"announcing"}', NULL, 4, 297, 501),
(298, 'annual', '/ˈænjuəl/', 'adjective', '{"zh-TW":["年度的；每年的"],"en":["occurring once every year"]}', '{"root":{"text":"annu","meaning":"year (年)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"與年有關的，即「年度的」。"}', 'annual report/meeting/revenue; annual report / annual meeting / annual income', '[{"en":"The annual report shows a 15% increase in profit.","zh-TW":"年度報告顯示利潤增長了15%。"},{"en":"The annual conference is held in December.","zh-TW":"年度會議在十二月舉行。"},{"en":"The company holds its annual meeting in March.","zh-TW":"公司每年三月舉行年度會議。"},{"en":"What is your annual income?","zh-TW":"你的年收入是多少？"}]', '{"adverb":"annually"}', NULL, 2, 298, 6),
(299, 'annual general meeting', '/ˈænjuəl ˈdʒenərəl ˈmiːtɪŋ/', 'noun', '{"zh-TW":["年度股東大會"],"en":["a yearly meeting where shareholders vote on company matters"]}', NULL, 'hold an AGM / attend the AGM / annual general meeting agenda', '[{"en":"Shareholders voted on the dividend proposal at the annual general meeting.","zh-TW":"股東在年度股東大會上對股利提案進行了投票。"},{"en":"The CEO presented the annual report at the AGM.","zh-TW":"執行長在年度股東大會上呈報了年報。"}]', '{"abbreviation":"AGM"}', NULL, 5, 299, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(300, 'annual leave', '/ˈænjuəl liːv/', 'noun', '{"zh-TW":["年假；有薪假"],"en":["paid vacation time granted each year"]}', NULL, 'take annual leave / annual leave entitlement', '[{"en":"Employees receive 15 days of annual leave per year.","zh-TW":"員工每年獲得15天年假。"},{"en":"Please submit your annual leave request two weeks in advance.","zh-TW":"請提前兩週提交年假申請。"}]', NULL, NULL, 4, 300, NULL),
(301, 'annual report', '/ˈænjuəl rɪˈpɔːrt/', 'noun', '{"zh-TW":["年報；年度報告"],"en":["a comprehensive report on a company''s activities and financial performance"]}', NULL, 'publish an annual report / review the annual report / annual report filing', '[{"en":"The annual report highlighted strong revenue growth year over year.","zh-TW":"年報強調了年度收入的強勁增長。"},{"en":"Shareholders receive the annual report before the AGM.","zh-TW":"股東在年度股東大會前收到年報。"}]', NULL, NULL, 5, 301, NULL),
(302, 'annualized', '/ˈænjuəlaɪzd/', 'adjective', '{"zh-TW":["年化的；按年換算的"],"en":["converted to an annual rate or basis"]}', NULL, 'annualized return / annualized growth rate / annualized figure', '[{"en":"The annualized return on the portfolio was twelve percent.","zh-TW":"投資組合的年化回報率為百分之十二。"},{"en":"Annualized GDP growth figures smooth out seasonal fluctuations.","zh-TW":"年化GDP增長數字消除了季節性波動。"}]', '{"verb":"annualize","noun":"annualization"}', NULL, 4, 302, NULL),
(303, 'annuity', '/əˈnjuːɪti/', 'noun', '{"zh-TW":["年金"],"en":["a fixed sum paid annually as retirement or investment income"]}', NULL, 'annuity plan / purchase an annuity / annuity payment', '[{"en":"He invested in an annuity to secure retirement income.","zh-TW":"他投資年金以確保退休收入。"},{"en":"The pension scheme pays a monthly annuity after age 60.","zh-TW":"退休金計劃在60歲後每月支付年金。"}]', '{"adjective":"annuitized"}', NULL, 3, 303, NULL),
(304, 'anomalous', '/əˈnɒmələs/', 'adjective', '{"zh-TW":["異常的；反常的"],"en":["deviating from what is standard or normal"]}', NULL, 'anomalous result / anomalous behavior / anomalous reading', '[{"en":"The anomalous data point was investigated to determine its cause.","zh-TW":"對異常數據點進行了調查以確定其原因。"},{"en":"Anomalous voting patterns triggered an audit of the election results.","zh-TW":"異常的投票模式觸發了對選舉結果的審計。"}]', '{"adverb":"anomalously","noun":"anomaly"}', NULL, 3, 304, NULL),
(305, 'anomaly', '/''əˌnɒməli/', 'noun', '{"zh-TW":["異常；例外；不規則現象"],"en":["something that deviates from what is standard, normal, or expected"]}', NULL, 'detect an anomaly / statistical anomaly / identify an anomaly', '[{"en":"The data analyst flagged an anomaly in the sales figures that required investigation.","zh-TW":"數據分析師標記了銷售數字中需要調查的異常情況。"},{"en":"Scientists discovered an anomaly in the experimental results that led to a new hypothesis.","zh-TW":"科學家發現了實驗結果中的異常，引出了一個新假說。"}]', '{"adjective":"anomalous","adverb":"anomalously"}', NULL, 3, 305, NULL),
(306, 'anomaly detection', '/əˈnɒməli dɪˈtekʃən/', 'noun', '{"zh-TW":["異常偵測"],"en":["the identification of patterns that deviate from expected behavior"]}', NULL, 'perform anomaly detection / anomaly detection algorithm / real-time anomaly detection', '[{"en":"Anomaly detection systems flag unusual activity in network traffic.","zh-TW":"異常偵測系統標記網路流量中的異常活動。"},{"en":"Machine learning enhances anomaly detection in fraud prevention.","zh-TW":"機器學習增強了欺詐預防中的異常偵測。"}]', NULL, NULL, 5, 306, NULL),
(307, 'anomie', '/ˈænəmiː/', 'noun', '{"zh-TW":["社會失範；社會解組"],"en":["a state of social instability resulting from breakdown of norms"]}', NULL, 'experience anomie / social anomie / Durkheim''s anomie', '[{"en":"Rapid social change can create anomie by disrupting established norms.","zh-TW":"快速的社會變遷可能通過破壞既定規範來產生社會失範。"},{"en":"Anomie theory explains higher suicide rates during periods of social upheaval.","zh-TW":"失範理論解釋了社會動盪時期較高的自殺率。"}]', '{"adjective":"anomic"}', NULL, 2, 307, NULL),
(308, 'another', '/əˈnʌðər/', 'determiner', '{"zh-TW":["另一個；再一個"],"en":["one more; a different one"]}', NULL, 'one another / another way', '[{"en":"Would you like another cup of tea?","zh-TW":"你想再來一杯茶嗎？"},{"en":"Let''s try another approach.","zh-TW":"讓我們試試另一種方法。"}]', NULL, NULL, 3, 308, NULL),
(309, 'answer', '/ˈænsər/', 'noun', '{"zh-TW":["答案；回覆","答案；回答","回答；答案；接電話"],"en":["a reply","a solution","a reply to a question","a reply; to respond to a question or call"]}', NULL, 'in answer to / answer the phone; answer the phone / in answer to; answer the phone / answer a question / in answer to', '[{"en":"Please answer my email by Friday.","zh-TW":"請在週五前回覆我的電子郵件。"},{"en":"There is no easy answer to this.","zh-TW":"這個問題沒有簡單的答案。"},{"en":"I don''t know the answer.","zh-TW":"我不知道答案。"},{"en":"Please answer the phone.","zh-TW":"請接電話。"},{"en":"Please answer my question.","zh-TW":"請回答我的問題。"},{"en":"Nobody answered the door.","zh-TW":"沒人來應門。"}]', '{"noun":"answer","verb":"answer","adjective":"answerable"}', NULL, 2, 309, NULL),
(310, 'answerable', '/ˈɑːnsərəbl/', 'adjective', '{"zh-TW":["應負責的；應解釋的"],"en":["required to account for actions or decisions to a higher authority"]}', NULL, 'answerable to the board / answerable for decisions', '[{"en":"The manager is answerable to the board for the division''s performance.","zh-TW":"管理者對部門績效向董事會負責。"},{"en":"All executives are answerable for their spending decisions.","zh-TW":"所有高管都應對其支出決策負責。"}]', NULL, NULL, 4, 310, NULL),
(311, 'antecedent', '/ˌæntɪˈsiːdənt/', 'noun', '{"zh-TW":["先行詞；前因"],"en":["something that precedes another; an ancestor or earlier condition"]}', NULL, 'historical antecedent / structural antecedent / causal antecedent', '[{"en":"Understanding the historical antecedents of a conflict is essential for resolution.","zh-TW":"了解衝突的歷史前因對於解決至關重要。"},{"en":"The study identifies antecedents of entrepreneurial intention in students.","zh-TW":"研究識別了學生創業意圖的前因。"}]', '{"adjective":"antecedent"}', NULL, 4, 311, NULL),
(312, 'anthropogenic', '/ˌænθrəpəˈdʒenɪk/', 'adjective', '{"zh-TW":["人為的；人類引起的"],"en":["originating in human activity"]}', NULL, 'anthropogenic emissions / anthropogenic climate change / anthropogenic factors', '[{"en":"Anthropogenic greenhouse gas emissions are the primary driver of global warming.","zh-TW":"人為溫室氣體排放是全球暖化的主要驅動力。"},{"en":"Anthropogenic noise pollution disrupts marine mammal communication.","zh-TW":"人為噪音污染破壞了海洋哺乳動物的溝通。"}]', NULL, NULL, 5, 312, NULL),
(313, 'anti-dumping duty', '/ˌænti ˈdʌmpɪŋ ˈdjuːti/', 'noun', '{"zh-TW":["反傾銷稅"],"en":["a tariff imposed to protect domestic industry from foreign goods sold below cost"]}', NULL, 'impose anti-dumping duties / anti-dumping duty investigation', '[{"en":"The government imposed anti-dumping duties on cheap imported steel.","zh-TW":"政府對進口廉價鋼鐵徵收了反傾銷稅。"},{"en":"An anti-dumping duty investigation requires proof of material injury.","zh-TW":"反傾銷稅調查需要提供實質損害的證明。"}]', NULL, NULL, 5, 313, NULL),
(314, 'antibiotic', '/ˌæntɪbaɪˈɒtɪk/', 'noun', '{"zh-TW":["抗生素"],"en":["a medicine that kills bacteria"]}', NULL, 'take an antibiotic / antibiotic resistance', '[{"en":"The doctor prescribed a course of antibiotics.","zh-TW":"醫生開了一個療程的抗生素。"},{"en":"Do not stop taking antibiotics before the course is finished.","zh-TW":"在療程結束前不要停止服用抗生素。"}]', '{"adjective":"antibiotic"}', NULL, 4, 314, NULL),
(315, 'antibiotic resistance', '/ˌæntɪbaɪˈɒtɪk rɪˈzɪstəns/', 'noun', '{"zh-TW":["抗生素耐藥性"],"en":["the ability of bacteria to withstand antibiotic treatment"]}', NULL, 'combat antibiotic resistance / antibiotic resistance crisis / spread of antibiotic resistance', '[{"en":"Overuse of antibiotics is the primary driver of antibiotic resistance.","zh-TW":"抗生素的過度使用是抗生素耐藥性的主要驅動力。"},{"en":"Antibiotic resistance threatens to make common infections untreatable.","zh-TW":"抗生素耐藥性威脅著使常見感染變得無法治療。"}]', '{"adjective":"antibiotic-resistant"}', NULL, 5, 315, NULL),
(316, 'anticipate', '/ænˈtɪsɪpeɪt/', 'verb', '{"zh-TW":["預期；預料"],"en":["to expect or predict something"]}', '{"prefix":{"text":"anti-","meaning":"before (之前)"},"root":{"text":"cip","meaning":"take (拿)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"在之前就拿取（準備），即「預期」。"}', 'anticipate demand/problems/growth', '[{"en":"We anticipate strong demand for the new product.","zh-TW":"我們預期新產品會有強勁需求。"},{"en":"The delay was not anticipated.","zh-TW":"這個延遲是始料未及的。"}]', '{"noun":"anticipation"}', NULL, 4, 316, 502),
(317, 'antioxidant', '/''æntiˈɒksɪdənt/', 'noun', '{"zh-TW":["抗氧化劑；抗氧化物"],"en":["a substance that prevents or slows damage to cells caused by free radicals"]}', NULL, 'rich in antioxidants / antioxidant supplement / natural antioxidant', '[{"en":"Blueberries and dark chocolate are rich in antioxidants.","zh-TW":"藍莓和黑巧克力富含抗氧化劑。"},{"en":"Many people take antioxidant supplements to support immune health.","zh-TW":"許多人服用抗氧化劑補充品來支持免疫健康。"}]', '{"adjective":"antioxidant-rich"}', NULL, 4, 317, NULL),
(318, 'antitrust', '/ˌæntiˈtrʌst/', 'adjective', '{"zh-TW":["反托拉斯的；反壟斷的"],"en":["relating to legislation preventing monopolistic business practices"]}', NULL, 'antitrust law / antitrust investigation / antitrust violation', '[{"en":"The merger was blocked following an antitrust investigation.","zh-TW":"合併在反托拉斯調查後被阻止了。"},{"en":"Antitrust regulators scrutinize mergers to protect market competition.","zh-TW":"反托拉斯監管機構審查合併以保護市場競爭。"}]', NULL, NULL, 3, 318, NULL),
(319, 'antitrust law', '/ˈæntitrʌst lɔː/', 'noun', '{"zh-TW":["反托拉斯法；競爭法"],"en":["legislation preventing anti-competitive business practices and monopolies"]}', NULL, 'comply with antitrust law / antitrust law investigation', '[{"en":"The merger was blocked by antitrust law authorities on competition grounds.","zh-TW":"合併被反托拉斯法機關以競爭理由阻止了。"},{"en":"Antitrust law promotes fair competition and protects consumer interests.","zh-TW":"反托拉斯法促進公平競爭並保護消費者利益。"}]', '{"synonym":"competition law"}', NULL, 5, 319, NULL),
(320, 'anxious', '/ˈæŋkʃəs/', 'adjective', '{"zh-TW":["焦慮的；擔心的"],"en":["feeling worried or nervous"]}', '{"root":{"text":"anx","meaning":"choke/distress (窒息/痛苦)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿痛苦不安的，即「焦慮的」。"}', 'feel anxious / anxious about', '[{"en":"She felt anxious about the job interview.","zh-TW":"她對工作面試感到焦慮。"},{"en":"He was anxious to hear the results.","zh-TW":"他急切地想知道結果。"}]', '{"noun":"anxiety","adverb":"anxiously"}', NULL, 3, 320, NULL),
(321, 'anybody', '/ˈɛnibɒdi/', 'pronoun', '{"zh-TW":["任何人"],"en":["any person at all"]}', NULL, 'anybody else / not anybody', '[{"en":"Is anybody home?","zh-TW":"有人在家嗎？"},{"en":"Anybody can learn to cook.","zh-TW":"任何人都能學會做飯。"}]', NULL, NULL, 3, 321, NULL),
(322, 'anyone', '/ˈeniwʌn/', 'pronoun', '{"zh-TW":["任何人"],"en":["any person; it doesn''t matter who"]}', NULL, 'anyone else', '[{"en":"Is anyone here?","zh-TW":"有人在嗎？"},{"en":"Anyone can apply for this position.","zh-TW":"任何人都可以申請這個職位。"}]', NULL, NULL, 2, 322, NULL),
(323, 'anything', '/ˈɛniθɪŋ/', 'pronoun', '{"zh-TW":["任何事物"],"en":["any thing at all","any thing; it doesn''t matter what"]}', NULL, 'anything else / not anything; anything else / if anything', '[{"en":"Is there anything I can do?","zh-TW":"有什麼我能做的嗎？"},{"en":"She didn''t say anything.","zh-TW":"她什麼都沒說。"},{"en":"Is there anything I can help with?","zh-TW":"有什麼我可以幫忙的嗎？"},{"en":"I''ll do anything to pass the exam.","zh-TW":"我會做任何事來通過考試。"}]', NULL, NULL, 3, 323, NULL),
(324, 'anywhere', '/ˈɛniwɛr/', 'adverb', '{"zh-TW":["任何地方"],"en":["in or to any place"]}', NULL, 'anywhere else / not anywhere', '[{"en":"You can sit anywhere you like.","zh-TW":"你可以坐任何你喜歡的位置。"},{"en":"I can''t find it anywhere.","zh-TW":"我哪裡都找不到它。"}]', NULL, NULL, 3, 324, NULL),
(325, 'apart', '/əˈpɑːrt/', 'adverb', '{"zh-TW":["分開地；相隔"],"en":["separated by distance or time"]}', NULL, 'apart from / fall apart', '[{"en":"They live far apart.","zh-TW":"他們住得很遠。"},{"en":"The old building is falling apart.","zh-TW":"那棟老建築正在坍塌。"}]', NULL, NULL, 2, 325, NULL),
(326, 'apartheid', '/əˈpɑːrtaɪd/', 'noun', '{"zh-TW":["種族隔離"],"en":["a former system of institutional racial segregation in South Africa; any analogous form of segregation"]}', NULL, 'apartheid regime / post-apartheid / apartheid era', '[{"en":"Nelson Mandela led the movement to end apartheid in South Africa.","zh-TW":"納爾遜·曼德拉領導了終結南非種族隔離的運動。"},{"en":"Social apartheid persists when economic inequality limits access to opportunity.","zh-TW":"當經濟不平等限制獲得機會時，社會隔離就會持續存在。"}]', NULL, NULL, 3, 326, NULL),
(327, 'apartment', '/əˈpɑːrtmənt/', 'noun', '{"zh-TW":["公寓"],"en":["a residential unit in a building","a set of rooms for living in, usually on one floor of a building"]}', NULL, 'apartment complex / rent an apartment; apartment building / studio apartment', '[{"en":"She rents an apartment near the office.","zh-TW":"她在辦公室附近租了一間公寓。"},{"en":"The apartment comes fully furnished.","zh-TW":"這間公寓有全套家具。"},{"en":"They rented a two-bedroom apartment.","zh-TW":"他們租了一間兩房公寓。"},{"en":"The apartment complex has a swimming pool.","zh-TW":"這個公寓大樓有游泳池。"}]', '{"noun":"apartment"}', NULL, 3, 327, NULL),
(328, 'aperitif', '/əˈpɛrɪtiːf/', 'noun', '{"zh-TW":["餐前酒；開胃飲料"],"en":["an alcoholic drink served before a meal"]}', NULL, 'order an aperitif / classic aperitif', '[{"en":"The waiter offered an aperitif while we looked at the menu.","zh-TW":"我們看菜單時，服務生提供了餐前酒。"},{"en":"A dry sherry is a popular aperitif in Spain.","zh-TW":"干雪利酒是西班牙受歡迎的餐前酒。"}]', NULL, NULL, 3, 328, NULL),
(329, 'aphorism', '/ˈæfərɪzəm/', 'noun', '{"zh-TW":["格言；警句"],"en":["a short pithy statement expressing a general truth"]}', NULL, 'memorable aphorism / classical aphorism / witty aphorism', '[{"en":"The essay opens with an aphorism that summarizes its central argument.","zh-TW":"文章以一句概括其核心論點的格言開頭。"},{"en":"Aphorisms distill complex wisdom into a single memorable phrase.","zh-TW":"格言將複雜的智慧濃縮成一句令人難忘的話。"}]', '{"adjective":"aphoristic"}', NULL, 3, 329, NULL),
(330, 'API', '/ˌeɪ piː ˈaɪ/', 'noun', '{"zh-TW":["應用程式介面"],"en":["application programming interface; allows software systems to communicate"]}', NULL, 'API integration / RESTful API / open API / API documentation', '[{"en":"The API allows third-party developers to build on the platform.","zh-TW":"API允許第三方開發者在平台上構建應用程式。"},{"en":"Seamless API integration was key to the digital transformation project.","zh-TW":"無縫的API整合是數位轉型項目的關鍵。"}]', '{"full form":"application programming interface"}', NULL, 1, 330, NULL),
(331, 'API endpoint', '/eɪ piː aɪ ˈendpɔɪnt/', 'noun', '{"zh-TW":["API端點"],"en":["a specific URL where an API receives requests"]}', NULL, 'call an API endpoint / expose an API endpoint / secure an API endpoint', '[{"en":"Each API endpoint handles a specific type of request.","zh-TW":"每個API端點處理特定類型的請求。"},{"en":"The developer documented all API endpoints for frontend integration.","zh-TW":"開發者記錄了所有API端點以供前端整合。"}]', NULL, NULL, 4, 331, NULL),
(332, 'API gateway', '/eɪ piː aɪ ˈɡeɪtweɪ/', 'noun', '{"zh-TW":["API閘道"],"en":["a server that acts as an entry point for client requests to backend services"]}', NULL, 'deploy an API gateway / configure an API gateway / API gateway security', '[{"en":"The API gateway handles authentication, rate limiting, and load balancing.","zh-TW":"API閘道處理身份驗證、速率限制和負載平衡。"},{"en":"An API gateway simplifies microservices architecture for clients.","zh-TW":"API閘道為客戶端簡化微服務架構。"}]', NULL, NULL, 4, 332, NULL),
(333, 'apology', 'əˈpɒlədʒi', 'noun', '{"zh-TW":["道歉；歉意","辯護"],"en":["an expression of regret","a statement of being sorry"]}', NULL, 'offer an apology/formal apology', '[{"en":"Please accept our sincere apology for the delay.","zh-TW":"請接受我們對延誤的誠摯道歉。"}]', '{"verb":"apologize","adjective":"apologetic","adverb":"apologetically"}', NULL, 3, 333, NULL),
(334, 'apparent', '/əˈpærənt/', 'adjective', '{"zh-TW":["明顯的；顯然的"],"en":["clearly visible or understood; obvious"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"par","meaning":"appear (出現)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"朝向出現的，即「明顯的」。"}', 'become apparent / for no apparent reason', '[{"en":"It became apparent that the project would exceed budget.","zh-TW":"很明顯該專案將超出預算。"},{"en":"The benefits are apparent to everyone involved.","zh-TW":"好處對所有相關人員都是顯而易見的。"}]', '{"adverb":"apparently"}', NULL, 3, 334, NULL),
(335, 'appeal', '/əˈpiːl/', 'verb', '{"zh-TW":["呼籲；上訴","吸引","吸引；呼籲；上訴"],"en":["to make a serious request","to be attractive or interesting","to attract or be interesting"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"peal","meaning":"drive/push (推動)"},"logic":"朝向推動人，即「呼籲、吸引」。"}', 'appeal to / appeal a decision; appeal to / appeal a decision / sex appeal', '[{"en":"The product appeals to health-conscious consumers.","zh-TW":"該產品吸引注重健康的消費者。"},{"en":"The company plans to appeal the court''s decision.","zh-TW":"公司計劃對法院判決提出上訴。"},{"en":"The idea doesn''t appeal to me.","zh-TW":"這個想法不吸引我。"},{"en":"They appealed the court''s decision.","zh-TW":"他們對法院的判決提出上訴。"}]', '{"adjective":"appealing","noun":"appeal"}', NULL, 2, 335, 503),
(336, 'appear', '/əˈpɪər/', 'verb', '{"zh-TW":["出現；似乎","出現；似乎；看起來"],"en":["to become visible","to seem or give the impression","to become visible; to seem"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"pear","meaning":"be visible (可見)"},"logic":"朝向可見，即「出現」。"}', 'appear to be / appear on/in; appear to be / appear in; appear to be / it appears that', '[{"en":"The error appears to have been corrected.","zh-TW":"這個錯誤似乎已被更正。"},{"en":"New opportunities appear as the market evolves.","zh-TW":"隨著市場發展，新機會不斷出現。"},{"en":"Stars appear at night.","zh-TW":"星星在夜晚出現。"},{"en":"He appears to be happy.","zh-TW":"他看起來很開心。"},{"en":"A new store appeared on our street.","zh-TW":"一家新店出現在我們的街上。"},{"en":"He appears to be very busy.","zh-TW":"他看起來非常忙碌。"}]', '{"noun":"appearance","adjective":"apparent","adverb":"apparently"}', NULL, 2, 336, NULL),
(337, 'appellate', '/əˈpelɪt/', 'adjective', '{"zh-TW":["上訴的；具有上訴管轄權的"],"en":["relating to legal appeals"]}', NULL, 'appellate court / appellate jurisdiction / appellate review', '[{"en":"The case was appealed to the appellate court for further review.","zh-TW":"案件被上訴至上訴法院進行進一步審查。"},{"en":"Appellate decisions set precedents that lower courts must follow.","zh-TW":"上訴法院的決定確立了下級法院必須遵循的先例。"}]', '{"noun":"appellant"}', NULL, 3, 337, NULL),
(338, 'appendix', '/əˈpɛndɪks/', 'noun', '{"zh-TW":["附錄；附件"],"en":["additional material at the end of a document"]}', NULL, 'see the appendix / attached appendix', '[{"en":"Detailed financial data can be found in the appendix.","zh-TW":"詳細的財務數據可以在附錄中找到。"},{"en":"Please refer to Appendix C for the supporting documentation.","zh-TW":"請參閱附錄C獲取支持文件。"}]', '{"plural":"appendices"}', NULL, 3, 338, NULL),
(339, 'appetizer', '/ˈæpɪtaɪzər/', 'noun', '{"zh-TW":["開胃菜；前菜"],"en":["a small dish served before the main course"]}', NULL, 'order an appetizer / light appetizer', '[{"en":"We shared a few appetizers before the main course.","zh-TW":"我們在主菜前共享了幾道開胃菜。"},{"en":"The appetizer menu includes soup and salad options.","zh-TW":"開胃菜菜單包含湯品和沙拉選項。"}]', '{"adjective":"appetizing"}', NULL, 3, 339, NULL),
(340, 'apple', '/ˈæpl/', 'noun', '{"zh-TW":["蘋果"],"en":["a round fruit with red, green, or yellow skin"]}', NULL, 'apple pie / apple juice', '[{"en":"An apple a day keeps the doctor away.","zh-TW":"一天一蘋果，醫生遠離我。"},{"en":"She bought some apples at the market.","zh-TW":"她在市場買了一些蘋果。"}]', NULL, NULL, 2, 340, NULL),
(341, 'applicability', '/ˌæplɪkəˈbɪlɪti/', 'noun', '{"zh-TW":["適用性；適用範圍"],"en":["the quality of being relevant or appropriate"]}', NULL, 'applicability of a rule / wide applicability', '[{"en":"Check the applicability of the policy to your department.","zh-TW":"查看該政策對您部門的適用性。"},{"en":"The new regulation has wide applicability across industries.","zh-TW":"新法規在各行業具有廣泛的適用性。"}]', '{"adjective":"applicable","verb":"apply"}', NULL, 5, 341, NULL),
(342, 'applicable', '/əˈplɪkəbl/', 'adjective', '{"zh-TW":["適用的；可應用的"],"en":["relevant or appropriate to a situation"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠朝向應用的，即「適用的」。"}', 'applicable to / where applicable', '[{"en":"This discount is applicable to orders over $100.","zh-TW":"此折扣適用於超過100美元的訂單。"},{"en":"Please fill in all applicable fields on the form.","zh-TW":"請填寫表格上所有適用的欄位。"}]', '{"noun":"applicability"}', NULL, 4, 342, 264),
(343, 'applicable law', '/ˈæplɪkəbl lɔː/', 'noun', '{"zh-TW":["適用法律"],"en":["the body of law that governs a contract or transaction"]}', NULL, 'specify applicable law / under applicable law', '[{"en":"The contract is governed by and construed in accordance with applicable law.","zh-TW":"合約受適用法律管轄並依其解釋。"},{"en":"Both parties agreed that applicable law would be English law.","zh-TW":"雙方同意適用法律為英國法律。"}]', NULL, NULL, 5, 343, NULL),
(344, 'applicant', '/ˈæplɪkənt/', 'noun', '{"zh-TW":["申請人；應徵者"],"en":["a person who applies for something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-ant","meaning":"person who (…的人)"},"logic":"朝向應用的人，即「申請人」。"}', 'job applicant / successful applicant', '[{"en":"We received over 200 applicants for the position.","zh-TW":"我們收到了超過200位該職位的應徵者。"},{"en":"Successful applicants will be notified by email.","zh-TW":"錄取者將以電子郵件通知。"}]', '{"noun":"application","verb":"apply"}', NULL, 3, 344, NULL),
(345, 'application', '/ˌæplɪˈkeɪʃən/', 'noun', '{"zh-TW":["應用程式；申請"],"en":["a computer program; a formal request"]}', NULL, 'mobile application / job application', '[{"en":"Download the application from the store.","zh-TW":"從商店下載這個應用程式。"},{"en":"I submitted my job application.","zh-TW":"我提交了工作申請。"}]', '{"verb":"apply","noun2":"applicant"}', NULL, 4, 345, 7),
(346, 'application programming interface', '/ˌæplɪˈkeɪʃən ˌproʊɡræmɪŋ ˈɪntərfeɪs/', 'noun', '{"zh-TW":["應用程式介面"],"en":["a set of rules allowing different software applications to communicate"]}', NULL, 'API integration / REST API / API documentation', '[{"en":"The payment gateway connects via an API to our e-commerce platform.","zh-TW":"支付閘道通過API連接到我們的電子商務平台。"},{"en":"Developers used the API to build a mobile application.","zh-TW":"開發人員使用API構建了行動應用程式。"}]', '{"abbreviation":"API"}', NULL, 5, 346, NULL),
(347, 'apply', '/əˈplaɪ/', 'verb', '{"zh-TW":["申請；應用"],"en":["to make a formal request","to put into operation or use"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"ply","meaning":"fold (折疊/靠近)"},"logic":"朝向靠近，即「申請、應用」。"}', 'apply for a job / apply knowledge', '[{"en":"She applied for the marketing manager position.","zh-TW":"她應徵了行銷經理職位。"},{"en":"Students learn how to apply theory to practice.","zh-TW":"學生學習如何將理論應用於實踐。"}]', '{"noun":"application","adjective":"applicable"}', NULL, 2, 347, NULL),
(348, 'appoint', '/əˈpɔɪnt/', 'verb', '{"zh-TW":["任命；指定"],"en":["to officially choose someone for a position"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"point","meaning":"point (指)"},"logic":"朝向指定某人，即「任命」。"}', 'appoint a director/representative', '[{"en":"The board appointed a new chief financial officer.","zh-TW":"董事會任命了新的財務長。"},{"en":"She was appointed to lead the project team.","zh-TW":"她被指定領導專案團隊。"}]', '{"noun":"appointment"}', NULL, 3, 348, 8),
(349, 'appointment', '/əˈpɔɪntmənt/', 'noun', '{"zh-TW":["預約；約診"],"en":["an arrangement to meet a doctor at a set time"]}', NULL, 'make an appointment / doctor appointment', '[{"en":"I need to make an appointment with my doctor.","zh-TW":"我需要預約我的醫生。"},{"en":"Please arrive ten minutes before your appointment.","zh-TW":"請在預約時間前十分鐘到達。"}]', '{"verb":"appoint","adjective":"appointed"}', NULL, 4, 349, 504);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(350, 'apportion', '/əˈpɔːrʃən/', 'verb', '{"zh-TW":["分攤；分配"],"en":["to divide and allocate something among parties"]}', NULL, 'apportion costs / apportion responsibility / apportion blame', '[{"en":"Costs were apportioned equally between the three departments.","zh-TW":"費用在三個部門之間平均分攤。"},{"en":"Responsibility was apportioned based on each party''s contribution.","zh-TW":"責任根據各方的貢獻進行了分攤。"}]', '{"noun":"apportionment"}', NULL, 3, 350, 984),
(351, 'apportionment', '/əˈpɔːrʃənmənt/', 'noun', '{"zh-TW":["分攤；分配"],"en":["the division of something among several parties"]}', NULL, 'cost apportionment / apportionment of expenses', '[{"en":"The apportionment of shared costs was agreed between divisions.","zh-TW":"共同成本的分攤在各部門之間達成了一致。"},{"en":"An equitable apportionment method was used for overhead allocation.","zh-TW":"採用了公平的分攤方法分配間接費用。"}]', '{"verb":"apportion"}', NULL, 5, 351, NULL),
(352, 'appraisal', '/əˈpreɪzəl/', 'noun', '{"zh-TW":["績效考核；評估"],"en":["a formal assessment of an employee''s job performance"]}', NULL, 'performance appraisal / annual appraisal / appraisal interview', '[{"en":"She received positive feedback during her annual appraisal.","zh-TW":"她在年度考核中收到了正面的反饋。"},{"en":"The appraisal system was redesigned to align with company values.","zh-TW":"考核制度被重新設計以與公司價值觀保持一致。"}]', '{"verb":"appraise","noun":"appraiser"}', NULL, 3, 352, 505),
(353, 'appraisal cycle', '/əˈpreɪzəl ˈsaɪkəl/', 'noun', '{"zh-TW":["考核週期"],"en":["the recurring schedule of performance evaluations in an organization"]}', NULL, 'annual appraisal cycle / mid-year appraisal cycle', '[{"en":"The annual appraisal cycle runs from January to December.","zh-TW":"年度考核週期從一月到十二月。"},{"en":"Employees set goals at the start of each appraisal cycle.","zh-TW":"員工在每個考核週期開始時設定目標。"}]', NULL, NULL, 5, 353, NULL),
(354, 'appraise', '/əˈpreɪz/', 'verb', '{"zh-TW":["評估；鑑定"],"en":["to assess the value or quality of something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"praise","meaning":"price/value (價值)"},"logic":"朝向評定價值，即「評估」。"}', 'appraise performance/property/value', '[{"en":"The property was appraised at $1.2 million.","zh-TW":"該房產被估價為120萬美元。"},{"en":"Managers appraise staff performance annually.","zh-TW":"經理每年評估員工績效。"}]', '{"noun":"appraisal"}', NULL, 3, 354, NULL),
(355, 'appreciate', '/əˈpriːʃieɪt/', 'verb', '{"zh-TW":["【主要意義-動詞】感激；欣賞","【次要意義-動詞】理解；意識到（某事的重要性/困難）","【次要意義-動詞】（資產）升值；增值"],"en":["[primary] to recognize and enjoy the value of something; to be grateful","[secondary] to fully understand a situation or problem","[secondary] to increase in value over time"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"preci","meaning":"price/value (價值)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"朝向認識價值，即「感謝、增值」。"}', 'appreciate the difficulty / appreciate your support / property appreciates', '[{"en":"I appreciate the difficulty of implementing these changes within one week.","zh-TW":"我理解在一周內實施這些變更的難度。"},{"en":"Real estate in the area has appreciated significantly over the past decade.","zh-TW":"該地區的房地產在過去十年中大幅升值。"},{"en":"We appreciate your patience while we resolve the technical issues.","zh-TW":"我們感謝您在我們解決技術問題期間的耐心等待。"}]', '{"noun":"appreciation","adjective":"appreciative"}', 'appreciate 的次要意義：「理解/意識到」（appreciate the complexity = 理解複雜性）和「升值」（assets appreciate），在 TOEIC 財務和商業文章中常見，考生常誤以為只有「感激/欣賞」的意思。', 4, 355, 265),
(356, 'appreciation', '/əˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["感謝；升值；欣賞"],"en":["gratitude; or an increase in value"]}', NULL, 'express appreciation / currency appreciation', '[{"en":"We wish to express our appreciation for your support.","zh-TW":"我們謹向您的支持表示感謝。"},{"en":"The appreciation of the property value doubled their investment.","zh-TW":"房產增值使他們的投資翻了一倍。"}]', '{"verb":"appreciate","adjective":"appreciated"}', NULL, 4, 356, NULL),
(357, 'apprehensive', '/''æprɪˌhensɪv/', 'adjective', '{"zh-TW":["憂慮的；擔心的"],"en":["anxious or fearful that something bad or unpleasant will happen"]}', NULL, 'apprehensive about / feel apprehensive / apprehensive of', '[{"en":"She was apprehensive about her first day at the new job.","zh-TW":"她對新工作的第一天感到擔心。"},{"en":"The entire team was apprehensive about the upcoming performance review.","zh-TW":"整個團隊都對即將到來的績效評估感到憂慮。"}]', '{"adverb":"apprehensively","noun":"apprehension"}', NULL, 4, 357, NULL),
(358, 'apprenticeship', '/''əˈprentɪsʃɪp/', 'noun', '{"zh-TW":["學徒期；學徒訓練"],"en":["a period of time working as an apprentice under a skilled worker to learn a trade or profession"]}', NULL, 'serve an apprenticeship / complete an apprenticeship / formal apprenticeship', '[{"en":"She completed a three-year apprenticeship before becoming a licensed electrician.","zh-TW":"她在成為持牌電工之前完成了為期三年的學徒訓練。"},{"en":"Apprenticeships offer a practical alternative to university education.","zh-TW":"學徒制提供了一種大學教育的實際替代選擇。"}]', '{"noun":"apprentice"}', NULL, 5, 358, NULL),
(359, 'approach', '/əˈprəʊtʃ/', 'noun', '{"zh-TW":["方法；途徑","接近"],"en":["a way of dealing with something","the act of coming near"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proach","meaning":"near (靠近)"},"logic":"朝向靠近，即「接近、方法」。"}', 'approach to / new approach', '[{"en":"We need a fresh approach to this problem.","zh-TW":"我們需要一個解決此問題的新方法。"},{"en":"The deadline is approaching rapidly.","zh-TW":"截止日期正在迅速逼近。"}]', '{"adjective":"approachable"}', NULL, 3, 359, NULL),
(360, 'appropriate', '/əˈprəʊpriət/', 'adjective', '{"zh-TW":["適當的；恰當的","適當的"],"en":["suitable or proper in the circumstances","suitable or proper for the circumstances"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"propri","meaning":"own (自己的)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向自己所有的，即「適當的」。"}', 'appropriate measures/behavior/response; appropriate behavior / appropriate response', '[{"en":"Please dress in appropriate business attire.","zh-TW":"請穿著適當的商務服裝。"},{"en":"The manager took appropriate action.","zh-TW":"經理採取了適當的行動。"},{"en":"Jeans are not appropriate for a formal dinner.","zh-TW":"牛仔褲不適合正式晚宴。"},{"en":"Please wear appropriate clothing.","zh-TW":"請穿著合適的服裝。"}]', '{"adverb":"appropriately","noun":"appropriateness"}', NULL, 4, 360, 266),
(361, 'appropriate funds', '/əˈproʊpriɪt fʌndz/', 'verb', '{"zh-TW":["撥款"],"en":["to set aside money for a specific official purpose"]}', NULL, 'appropriate funds for research / appropriated budget', '[{"en":"Congress appropriated additional funds for the disaster relief effort.","zh-TW":"國會為災難救援工作撥出了額外資金。"},{"en":"The board appropriated reserves to cover the unexpected expenses.","zh-TW":"董事會撥出了儲備金以支付意外費用。"}]', NULL, NULL, 5, 361, NULL),
(362, 'appropriation', '/əˌproʊpriˈeɪʃən/', 'noun', '{"zh-TW":["撥款；撥用"],"en":["the setting aside of funds for a specific purpose or authorized use"]}', NULL, 'budget appropriation / government appropriation', '[{"en":"The board approved the appropriation of $2 million for the R&D project.","zh-TW":"董事會批准了200萬元用於研發項目的撥款。"},{"en":"Government appropriations for infrastructure were increased in the budget.","zh-TW":"預算中增加了用於基礎設施的政府撥款。"}]', '{"verb":"appropriate"}', NULL, 5, 362, NULL),
(363, 'approval', '/əˈpruːvəl/', 'noun', '{"zh-TW":["批准；認可"],"en":["official agreement or permission"]}', NULL, 'require approval / pending approval', '[{"en":"Final approval is required from the board of directors.","zh-TW":"需要董事會的最終批准。"},{"en":"The budget proposal awaits management approval.","zh-TW":"預算提案正等待管理層批准。"}]', '{"verb":"approve","adjective":"approved"}', NULL, 3, 363, 9),
(364, 'approval process', '/əˈpruːvəl ˈprɒses/', 'noun', '{"zh-TW":["審批流程"],"en":["the formal steps required to review and authorize decisions or transactions"]}', NULL, 'follow the approval process / approval process delays', '[{"en":"All capital expenditures must go through the approval process.","zh-TW":"所有資本支出必須通過審批流程。"},{"en":"Streamlining the approval process reduced decision-making time by half.","zh-TW":"簡化審批流程將決策時間縮短了一半。"}]', NULL, NULL, 5, 364, NULL),
(365, 'approve', '/əˈpruːv/', 'verb', '{"zh-TW":["批准；核准","贊成"],"en":["to officially agree to or accept","to believe that something is good"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"prove","meaning":"test/good (驗證/好)"},"logic":"朝向好的，即「批准」。"}', 'approve a request/budget/plan', '[{"en":"The board approved the annual budget.","zh-TW":"董事會批准了年度預算。"},{"en":"The proposal was approved unanimously.","zh-TW":"該提案被一致通過。"}]', '{"noun":"approval"}', NULL, 3, 365, NULL),
(366, 'approved', 'əˈpruːvd', 'adjective', '{"zh-TW":["已批准的；獲批的","認可的"],"en":["officially accepted","meeting required standards"]}', NULL, 'approved supplier/approved budget', '[{"en":"Only approved vendors may be used.","zh-TW":"只能使用已批准的供應商。"}]', '{"verb":"approve","noun":"approval"}', NULL, 3, 366, NULL),
(367, 'approved vendor list', '/əˈpruːvd ˈvendər lɪst/', 'noun', '{"zh-TW":["核准供應商名單"],"en":["a list of suppliers that have been evaluated and approved for procurement use"]}', NULL, 'add to the approved vendor list / approved vendor list audit', '[{"en":"Only suppliers on the approved vendor list can receive purchase orders.","zh-TW":"只有在核准供應商名單上的供應商才能收到採購訂單。"},{"en":"The approved vendor list is reviewed annually for quality and compliance.","zh-TW":"核准供應商名單每年審查一次品質和合規情況。"}]', NULL, NULL, 5, 367, NULL),
(368, 'approximate', '/əˈprɒksɪmət/', 'adjective', '{"zh-TW":["大約的；近似的"],"en":["close to the actual but not completely exact"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proxim","meaning":"nearest (最近)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向最近的，即「近似的」。"}', 'approximate cost/time/value', '[{"en":"The approximate cost of the project is $500,000.","zh-TW":"該專案的大約成本為50萬美元。"},{"en":"Can you give me an approximate delivery date?","zh-TW":"你能給我一個大約的交貨日期嗎？"}]', '{"adverb":"approximately","noun":"approximation"}', NULL, 4, 368, NULL),
(369, 'approximately', '/əˈprɒksɪmətli/', 'adverb', '{"zh-TW":["大約"],"en":["close to an exact amount but not completely accurate"]}', '{"prefix":{"text":"ap-","meaning":"to (朝向)"},"root":{"text":"proxim","meaning":"near (接近)"},"suffix":{"text":"-ately","meaning":"in manner of (以…方式)"},"logic":"以接近的方式，即「大約」。"}', 'approximately 100 / takes approximately', '[{"en":"The project will take approximately six months.","zh-TW":"這個專案大約需要六個月。"},{"en":"Approximately 200 people attended the event.","zh-TW":"大約200人參加了活動。"}]', '{"adjective":"approximate","verb":"approximate","noun":"approximation"}', NULL, 5, 369, 10),
(370, 'apt', '/æpt/', 'adjective', '{"zh-TW":["恰當的；適合的"],"en":["appropriate or suitable in the circumstances"]}', NULL, 'apt description / apt choice', '[{"en":"She made an apt comparison between the two strategies.","zh-TW":"她在兩種策略之間做了恰當的比較。"},{"en":"His concise summary was an apt way to end the presentation.","zh-TW":"他的簡明摘要是結束簡報的恰當方式。"}]', '{"adverb":"aptly","noun":"aptness"}', NULL, 1, 370, NULL),
(371, 'aptitude test', '/ˈæptɪtjuːd tɛst/', 'noun', '{"zh-TW":["性向測驗；能力傾向測試"],"en":["a test measuring a person''s ability or potential"]}', NULL, 'take an aptitude test / aptitude test score', '[{"en":"The company uses aptitude tests to screen candidates.","zh-TW":"公司使用性向測驗篩選候選人。"},{"en":"Her aptitude test results showed strong analytical skills.","zh-TW":"她的性向測驗結果顯示出強大的分析能力。"}]', NULL, NULL, 5, 371, NULL),
(372, 'arbitrage', '/ˈɑːrbɪtrɑːʒ/', 'noun', '{"zh-TW":["套利"],"en":["profiting from price differences of the same asset in different markets"]}', NULL, 'risk arbitrage / currency arbitrage / exploit arbitrage opportunities', '[{"en":"Traders engage in arbitrage to profit from price discrepancies.","zh-TW":"交易者進行套利以從價格差異中獲利。"},{"en":"Arbitrage opportunities quickly disappear in efficient markets.","zh-TW":"套利機會在有效市場中迅速消失。"}]', '{"verb":"arbitrage","noun":"arbitrageur"}', NULL, 3, 372, NULL),
(373, 'arbitrageur', '/ˌɑːrbɪtrɑːˈʒɜːr/', 'noun', '{"zh-TW":["套利者"],"en":["a person who engages in arbitrage transactions"]}', NULL, 'market arbitrageur / merger arbitrageur / skilled arbitrageur', '[{"en":"The arbitrageur profited from price discrepancies across exchanges.","zh-TW":"套利者從交易所之間的價格差異中獲利。"},{"en":"Arbitrageurs help make markets more efficient.","zh-TW":"套利者有助於使市場更有效率。"}]', '{"noun2":"arbitrage","verb":"arbitrage"}', NULL, 4, 373, NULL),
(374, 'arbitral tribunal', '/ˈɑːrbɪtrəl traɪˈbjuːnəl/', 'noun', '{"zh-TW":["仲裁庭"],"en":["a panel of arbitrators that hears and decides a dispute"]}', NULL, 'convene an arbitral tribunal / establish an arbitral tribunal / arbitral tribunal award', '[{"en":"The parties agreed to submit the dispute to an arbitral tribunal.","zh-TW":"雙方同意將爭議提交仲裁庭。"},{"en":"The arbitral tribunal issued its award after six months of proceedings.","zh-TW":"仲裁庭在六個月的程序後發布了裁決。"}]', NULL, NULL, 5, 374, NULL),
(375, 'arbitrary', '/''ɑːrbɪtrɪri/', 'adjective', '{"zh-TW":["任意的；武斷的"],"en":["based on random choice or personal whim, rather than any reason or system"]}', NULL, 'arbitrary decision / arbitrary rule / arbitrary limit', '[{"en":"The policy seemed arbitrary and employees questioned its rationale.","zh-TW":"政策看起來很任意，員工們質疑其依據。"},{"en":"Setting an arbitrary deadline without considering workload leads to poor outcomes.","zh-TW":"在不考慮工作量的情況下設定任意截止日期會導致不良結果。"}]', '{"adverb":"arbitrarily","noun":"arbitrariness"}', NULL, 3, 375, NULL),
(376, 'arbitrate', '/ˈɑːrbɪtreɪt/', 'verb', '{"zh-TW":["仲裁；裁決"],"en":["to act as an impartial judge to resolve a dispute between parties"]}', NULL, 'arbitrate a dispute / arbitrate between parties', '[{"en":"An independent expert was appointed to arbitrate the contract dispute.","zh-TW":"任命了一名獨立專家仲裁合約糾紛。"},{"en":"The two sides agreed to arbitrate rather than go to court.","zh-TW":"雙方同意進行仲裁而不是上法院。"}]', '{"noun":"arbitration","noun2":"arbitrator"}', NULL, 3, 376, 646),
(377, 'arbitration', '/ˌɑːrbɪˈtreɪʃən/', 'noun', '{"zh-TW":["仲裁"],"en":["a method of resolving disputes outside of court using a neutral third party"]}', NULL, 'binding arbitration / arbitration clause / submit to arbitration / arbitration hearing', '[{"en":"The contract included an arbitration clause to resolve disputes.","zh-TW":"合約包含仲裁條款以解決糾紛。"},{"en":"Arbitration is faster and cheaper than litigation for commercial disputes.","zh-TW":"仲裁比訴訟更快且更便宜解決商業糾紛。"}]', '{"verb":"arbitrate","noun":"arbitrator"}', NULL, 4, 377, 749),
(378, 'arbitration agreement', '/ˌɑːrbɪˈtreɪʃən əˈɡriːmənt/', 'noun', '{"zh-TW":["仲裁協議"],"en":["a contract requiring parties to resolve disputes through arbitration"]}', NULL, 'sign an arbitration agreement / enforce an arbitration agreement', '[{"en":"The parties entered an arbitration agreement to avoid costly litigation.","zh-TW":"雙方簽訂了仲裁協議以避免代價高昂的訴訟。"},{"en":"An arbitration agreement specifies the governing rules and venue.","zh-TW":"仲裁協議規定了管轄規則和地點。"}]', NULL, NULL, 5, 378, NULL),
(379, 'arbitration clause', '/ˌɑːrbɪˈtreɪʃən klɔːz/', 'noun', '{"zh-TW":["仲裁條款"],"en":["a provision in a contract requiring disputes to be resolved by arbitration"]}', NULL, 'include an arbitration clause / binding arbitration clause', '[{"en":"The arbitration clause prevented costly court proceedings.","zh-TW":"仲裁條款防止了代價高昂的法庭訴訟。"},{"en":"Both parties agreed to include an arbitration clause in the contract.","zh-TW":"雙方同意在合約中加入仲裁條款。"}]', NULL, NULL, 5, 379, NULL),
(380, 'arbitrator', '/ˈɑːrbɪtreɪtər/', 'noun', '{"zh-TW":["仲裁人；仲裁員"],"en":["an independent person appointed to settle a dispute"]}', NULL, 'appoint an arbitrator / neutral arbitrator', '[{"en":"An independent arbitrator was appointed to resolve the pay dispute.","zh-TW":"任命了一名獨立仲裁員解決薪資糾紛。"},{"en":"The arbitrator''s decision is binding on both parties.","zh-TW":"仲裁員的裁決對雙方均具有約束力。"}]', '{"verb":"arbitrate","noun":"arbitration"}', NULL, 4, 380, NULL),
(381, 'archetype', '/ˈɑːrkɪtaɪp/', 'noun', '{"zh-TW":["原型；典型"],"en":["a very typical example of a certain person or thing"]}', NULL, 'cultural archetype / Jungian archetype / classic archetype', '[{"en":"The hero is a universal archetype found in all cultures.","zh-TW":"英雄是在所有文化中都能找到的普遍原型。"},{"en":"She became the archetype of the successful female entrepreneur.","zh-TW":"她成為成功女性企業家的典型代表。"}]', '{"adjective":"archetypal","adverb":"archetypally"}', NULL, 3, 381, NULL),
(382, 'architect', '/ˈɑːrkɪtekt/', 'noun', '{"zh-TW":["建築師"],"en":["a person who designs buildings"]}', '{"prefix":{"text":"archi-","meaning":"chief (首席)"},"root":{"text":"tect","meaning":"builder (建造者)"},"logic":"首席建造者，即「建築師」。"}', 'architect firm / landscape architect', '[{"en":"The architect designed a modern office building.","zh-TW":"建築師設計了一棟現代辦公大樓。"},{"en":"She hired an architect to redesign her home.","zh-TW":"她聘請建築師重新設計她的房子。"}]', '{"noun":"architecture","adjective":"architectural"}', NULL, 3, 382, NULL),
(383, 'archive', '/ˈɑːrkaɪv/', 'noun', '{"zh-TW":["檔案庫；存檔"],"en":["a collection of historical documents or records"]}', NULL, 'company archive / archive files', '[{"en":"All contracts are stored in the company archive.","zh-TW":"所有合約都存放在公司檔案庫中。"},{"en":"Please archive the completed project files.","zh-TW":"請將已完成的項目文件存檔。"}]', '{"verb":"archive","adjective":"archived"}', NULL, 3, 383, 825),
(384, 'arduous', '/ˈɑːrdʒuəs/', 'adjective', '{"zh-TW":["艱難的；費力的"],"en":["involving or requiring strenuous effort; difficult and tiring"]}', NULL, 'arduous task / arduous journey / arduous process', '[{"en":"The arduous process of building a startup from scratch taught her invaluable lessons.","zh-TW":"從零開始建立一家初創公司的艱難過程給她帶來了寶貴的教訓。"},{"en":"Climbing the mountain was arduous, but the view from the top was worth every step.","zh-TW":"攀登這座山既艱難又費力，但山頂的景色值得每一步的努力。"}]', '{"adverb":"arduously","noun":"arduousness"}', NULL, 3, 384, NULL),
(385, 'area', '/ˈɛriə/', 'noun', '{"zh-TW":["區域；面積"],"en":["a particular part of a place or subject"]}', NULL, 'in the area / area of expertise', '[{"en":"This area is known for its food.","zh-TW":"這個地區以美食聞名。"},{"en":"What''s the area of this room?","zh-TW":"這個房間的面積是多少？"}]', NULL, NULL, 1, 385, NULL),
(386, 'arguably', '/''ɑːrɡjʊəbli/', 'adverb', '{"zh-TW":["可以說；有理由認為"],"en":["it may be argued; used to say that something is probably true or can be supported with evidence"]}', NULL, 'arguably the best / arguably more important / arguably the most', '[{"en":"She is arguably the most influential figure in the company''s history.","zh-TW":"她可以說是公司歷史上最具影響力的人物。"},{"en":"The new strategy is arguably riskier but offers much higher rewards.","zh-TW":"新策略可以說風險更大，但提供了更高的回報。"}]', '{"adjective":"arguable"}', NULL, 3, 386, NULL),
(387, 'arise', '/əˈraɪz/', 'verb', '{"zh-TW":["出現；產生","出現；發生"],"en":["to come into being or to come to attention","to come into being; to occur"]}', '{"prefix":{"text":"a-","meaning":"up (向上)"},"root":{"text":"rise","meaning":"rise (升起)"},"logic":"升起來，即「出現」。"}', 'arise from / problems arise; problems arise / arise from / should the need arise', '[{"en":"Several issues arose during the negotiation.","zh-TW":"談判期間出現了幾個問題。"},{"en":"Opportunities may arise from this partnership.","zh-TW":"這個合作關係可能產生機會。"},{"en":"Unexpected problems arose during the project.","zh-TW":"專案期間出現了意料之外的問題。"},{"en":"Conflicts can arise from misunderstandings.","zh-TW":"衝突可能源於誤解。"}]', NULL, NULL, 2, 387, NULL),
(388, 'arm', '/ɑːrm/', 'noun', '{"zh-TW":["手臂；武器","手臂；武裝"],"en":["the body part from shoulder to hand","the body part between shoulder and hand; to supply with weapons"]}', NULL, 'arm in arm / open arms; arm in arm / armed with', '[{"en":"She broke her arm skiing.","zh-TW":"她滑雪時摔斷了手臂。"},{"en":"They welcomed us with open arms.","zh-TW":"他們張開雙臂歡迎我們。"},{"en":"She broke her arm in the accident.","zh-TW":"她在事故中摔斷了手臂。"},{"en":"The security guard was armed.","zh-TW":"保全人員有武裝。"}]', '{"noun":"armament","adjective":"armed, unarmed"}', NULL, 1, 388, NULL),
(389, 'arm''s length', '/ɑːrmz leŋθ/', 'adjective', '{"zh-TW":["公平交易的；公正的"],"en":["describing a transaction in which parties act independently and without influence"]}', NULL, 'arm''s length transaction / arm''s length pricing / arm''s length basis', '[{"en":"Tax authorities require related parties to transact on an arm''s length basis.","zh-TW":"稅務機關要求關聯方以公平交易為基礎進行交易。"},{"en":"The sale was conducted at arm''s length to avoid conflict of interest.","zh-TW":"銷售是在公平交易的基礎上進行的，以避免利益衝突。"}]', NULL, NULL, 4, 389, NULL),
(390, 'arm''s length price', '/ɑːrmz leŋθ praɪs/', 'noun', '{"zh-TW":["公平交易價格"],"en":["a price for a transaction set as if the parties were independent of each other"]}', NULL, 'determine arm''s length price / arm''s length pricing standard', '[{"en":"Tax authorities require related companies to transact at arm''s length prices.","zh-TW":"稅務機關要求關聯公司按公平交易價格進行交易。"},{"en":"An arm''s length price prevents profit shifting between group entities.","zh-TW":"公平交易價格防止了集團實體之間的利潤轉移。"}]', NULL, NULL, 5, 390, NULL),
(391, 'arms-length transaction', '/ɑːrmz leŋθ trænˈzækʃən/', 'noun', '{"zh-TW":["公平交易；獨立交易"],"en":["a transaction between unrelated parties dealing independently on equal terms"]}', NULL, 'conduct an arms-length transaction / arms-length transaction requirement', '[{"en":"Tax authorities require that related-party dealings be conducted at arms-length.","zh-TW":"稅務機關要求關聯方交易按公平交易原則進行。"},{"en":"An independent valuation confirms the deal is an arms-length transaction.","zh-TW":"獨立估值確認了該交易是公平交易。"}]', NULL, NULL, 5, 391, NULL),
(392, 'army', '/ˈɑːrmi/', 'noun', '{"zh-TW":["軍隊；陸軍"],"en":["the military land forces of a country"]}', NULL, 'join the army / army base', '[{"en":"He joined the army at 18.","zh-TW":"他18歲參軍。"},{"en":"The army was deployed overseas.","zh-TW":"軍隊被部署到海外。"}]', NULL, NULL, 1, 392, NULL),
(393, 'around', '/əˈraʊnd/', 'preposition', '{"zh-TW":["周圍；大約"],"en":["on all sides of; approximately"]}', NULL, 'around the world / look around', '[{"en":"There are trees around the house.","zh-TW":"房子周圍有樹。"},{"en":"It costs around fifty dollars.","zh-TW":"大約花費五十美元。"}]', NULL, NULL, 2, 393, NULL),
(394, 'arrange', '/əˈreɪndʒ/', 'verb', '{"zh-TW":["安排；籌備"],"en":["to plan or organize something in advance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"range","meaning":"rank/row (排列)"},"logic":"朝向排列，即「安排」。"}', 'arrange a meeting/event/delivery', '[{"en":"I''ll arrange a meeting with the client for next week.","zh-TW":"我會安排下週與客戶的會議。"},{"en":"Transportation has been arranged for all attendees.","zh-TW":"已為所有出席者安排了交通。"}]', '{"noun":"arrangement"}', NULL, 3, 394, 267),
(395, 'arrears', '/əˈrɪərz/', 'noun', '{"zh-TW":["欠款；拖欠款項"],"en":["unpaid debts or obligations that are overdue"]}', NULL, 'fall into arrears / pay off arrears', '[{"en":"The customer fell three months into arrears on the loan.","zh-TW":"客戶的貸款拖欠了三個月。"},{"en":"The company cleared all arrears on its supplier accounts.","zh-TW":"公司清除了供應商帳戶上的所有欠款。"}]', '{"singular":"arrearage"}', NULL, 3, 395, NULL),
(396, 'arrival', '/''əˈraɪvəl/', 'noun', '{"zh-TW":["到達；抵達"],"en":["the action or process of arriving at a place or destination"]}', NULL, 'upon arrival / arrival time / airport arrival', '[{"en":"Upon arrival at the hotel, guests receive a complimentary welcome drink.","zh-TW":"抵達飯店後，客人會收到免費的歡迎飲料。"},{"en":"Her arrival at the conference was greeted with enthusiastic applause.","zh-TW":"她抵達會議時，受到熱烈掌聲的歡迎。"}]', '{"verb":"arrive"}', NULL, 3, 396, NULL),
(397, 'arrive', '/əˈraɪv/', 'verb', '{"zh-TW":["到達；抵達"],"en":["to reach a destination","to reach a place after traveling"]}', NULL, 'arrive at / arrive on time; arrive at/in + 地點', '[{"en":"The shipment will arrive tomorrow.","zh-TW":"貨物明天會到達。"},{"en":"Please arrive 10 minutes early.","zh-TW":"請提前10分鐘到達。"},{"en":"The flight arrives at 3 PM.","zh-TW":"班機下午三點抵達。"},{"en":"We arrived in Tokyo yesterday.","zh-TW":"我們昨天到達東京。"}]', '{"verb":"arrive","noun":"arrival"}', NULL, 2, 397, NULL),
(398, 'arrogant', '/ˈærəɡənt/', 'adjective', '{"zh-TW":["傲慢的"],"en":["having an exaggerated sense of one''s importance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"rog","meaning":"ask/claim (要求)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對自己提出過高要求的，即「傲慢的」。"}', 'arrogant attitude / arrogant behavior', '[{"en":"His arrogant attitude made him unpopular.","zh-TW":"他傲慢的態度使他不受歡迎。"},{"en":"Don''t be so arrogant about your achievements.","zh-TW":"不要對你的成就如此傲慢。"}]', '{"noun":"arrogance"}', NULL, 3, 398, NULL),
(399, 'art', '/ɑːrt/', 'noun', '{"zh-TW":["藝術；美術"],"en":["the creation of beautiful or meaningful things"]}', NULL, 'work of art / art gallery', '[{"en":"She studies art at university.","zh-TW":"她在大學學藝術。"},{"en":"This painting is a true work of art.","zh-TW":"這幅畫是真正的藝術品。"}]', '{"noun":"artist","adjective":"artistic"}', NULL, 1, 399, NULL);